--
-- Table structure for table `project_documents`
--

DROP TABLE IF EXISTS `project_documents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `project_documents` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_id` int(11) NOT NULL,
  `location` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `inspection_date` date DEFAULT NULL,
  `inspection_officer_name_1` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `inspection_officer_role_1` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `inspection_officer_name_2` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `inspection_officer_role_2` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `inspection_description` text COLLATE utf8mb4_unicode_ci,
  `progress_date` date DEFAULT NULL,
  `progress_officer_name_1` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `progress_officer_role_1` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `progress_officer_name_2` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `progress_officer_role_2` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `progress_description` text COLLATE utf8mb4_unicode_ci,
  `handover_date` date DEFAULT NULL,
  `handover_officer_name_1` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `handover_officer_role_1` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `handover_officer_name_2` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `handover_officer_role_2` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `handover_description` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `company_1` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `company_2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `progress_status` int(11) DEFAULT NULL,
  `handover_status` int(11) DEFAULT NULL,
  `bapp_attachment` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `fk_project_document` (`project_id`),
  CONSTRAINT `fk_project_document` FOREIGN KEY (`project_id`) REFERENCES `portfolio_` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

