INSERT INTO `project_documents` VALUES (1,1,'Dana Pensiun Telkom','2026-06-24','Bambang Gunawan H','Manager Information System','Nava Gia Ginasta, M.Kom','Direktur Utama','<p style=\"text-align: justify;\">Bahwa&nbsp;<strong>PIHAK&nbsp;KEDUA&nbsp;</strong>telah&nbsp;menyelesaikan&nbsp;pekerjaan&nbsp;<em>Support&nbsp;</em>Pengembangan&nbsp;&amp;&nbsp;Pemeliharaan&nbsp;Aplikasi&nbsp;Dana&nbsp;Pensiun&nbsp;Telkom&nbsp;2026&nbsp;yang&nbsp;sesuai&nbsp;dengan&nbsp;Kontrak&nbsp;No:&nbsp;121/HK-71/Dapentel-020/2026&nbsp;periode&nbsp;Juni&nbsp;2026&nbsp;yang&nbsp;telah&nbsp;sesuai&nbsp;dengan&nbsp;TOR&nbsp;dengan&nbsp;detail&nbsp;sebagai&nbsp;berikut:</p><ol><li>Support&nbsp;Pengembanan&nbsp;Aplikasi.</li><li>Support&nbsp;Pemeliharaan&nbsp;Aplikasi.</li></ol><p style=\"text-align: justify;\">Detil&nbsp;dari&nbsp;pekerjaan&nbsp;tersebut&nbsp;terlampir&nbsp;pada&nbsp;Dokumen&nbsp;Laporan&nbsp;Pekerjaan&nbsp;atau&nbsp;dapat&nbsp;diakses&nbsp;melalui&nbsp;link&nbsp;<a href=\"https://bit.ly/DapenCrop2026\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: black;\">https://bit.ly/DapenCrop2026</a>.</p><p style=\"text-align: justify;\"><strong>PIHAK&nbsp;PERTAMA&nbsp;</strong>telah&nbsp;menerima&nbsp;hasil&nbsp;pelaksanaan&nbsp;pekerjaan&nbsp;berupa&nbsp;lampiran&nbsp;tersebut&nbsp;diatas&nbsp;hasil&nbsp;dari&nbsp;<em>Support&nbsp;</em>Pengembangan&nbsp;&amp;&nbsp;Pemeliharaan&nbsp;Aplikasi&nbsp;Dana&nbsp;Pensiun&nbsp;Telkom&nbsp;2026&nbsp;yang&nbsp;sesuai&nbsp;dengan&nbsp;Kontrak&nbsp;No:&nbsp;121/HK-71/Dapentel-020/2026&nbsp;periode&nbsp;Juni&nbsp;2026.</p><p style=\"text-align: justify;\"></p><p style=\"text-align: justify;\">Demikian&nbsp;berita&nbsp;acara&nbsp;pekerjaan&nbsp;(BAP)&nbsp;ini&nbsp;dibuat&nbsp;untuk&nbsp;dipergunakan&nbsp;sebagaimana&nbsp;mestinya.</p>','2026-05-23','Angkoso Suryocahyono','PGS VP Information System & Reporting','Nava Gia Ginasta, M.Kom','Direktur Utama','<p>Berdasarkan&nbsp;Kontrak&nbsp;Perjanjian&nbsp;Kerja&nbsp;Sama&nbsp;<strong>Support&nbsp;Pengembangan&nbsp;&amp;&nbsp;Pemeliharaan&nbsp;Aplikasi&nbsp;Dana&nbsp;Pensiun&nbsp;Telkom</strong>&nbsp;No:&nbsp;<strong>Tel.23/LG&nbsp;270/JDPT-0203000/2026</strong>&nbsp;tanggal&nbsp;<strong>11&nbsp;Mei&nbsp;2026</strong></p><p>Dengan&nbsp;ini&nbsp;menerangkan&nbsp;bahwa:</p><ol><li><strong>PIHAK&nbsp;KEDUA</strong>&nbsp;menyatakan&nbsp;telah&nbsp;menyelesaikan&nbsp;pekerjaan&nbsp;sesuai&nbsp;ruang&nbsp;lingkup&nbsp;dan&nbsp;deliverables&nbsp;pengadaan&nbsp;<strong>Support&nbsp;Pengembangan&nbsp;&amp;&nbsp;Pemeliharaan&nbsp;Aplikasi&nbsp;Dana&nbsp;Pensiun&nbsp;Telkom</strong>&nbsp;sesuai&nbsp;dengan&nbsp;Kontrak&nbsp;Perjanjian&nbsp;Kerja&nbsp;Sama&nbsp;No:&nbsp;<strong>Tel.23/LG&nbsp;270/JDPT-0203000/2026</strong></li><li><strong>PIHAK&nbsp;PERTAMA</strong>&nbsp;menyatakan&nbsp;telah&nbsp;memeriksa&nbsp;hasil&nbsp;pekerjaan&nbsp;dan&nbsp;deliverables&nbsp;dimaksud&nbsp;pada&nbsp;butir&nbsp;1&nbsp;dengan&nbsp;hasil&nbsp;Baik&nbsp;dan&nbsp;Sesuai.</li><li>Laporan&nbsp;hasil&nbsp;dan/atau&nbsp;checklist&nbsp;penyelesaian&nbsp;pekerjaan&nbsp;sebagaimana&nbsp;terlampir.</li></ol><p>Demikian&nbsp;Berita&nbsp;Acara&nbsp;Penyelesaian&nbsp;Pekerjaan&nbsp;(BAPP)&nbsp;<strong>Support&nbsp;Pengembangan&nbsp;&amp;&nbsp;Pemeliharaan&nbsp;Aplikasi&nbsp;Dana&nbsp;Pensiun&nbsp;Telkom</strong>&nbsp;ini&nbsp;dibuat&nbsp;dalam&nbsp;rangkap&nbsp;2&nbsp;(dua)&nbsp;asli,&nbsp;masing-masing&nbsp;sama&nbsp;bunyinya&nbsp;serta&nbsp;mempunyai&nbsp;kekuatan&nbsp;hukum&nbsp;yang&nbsp;sama&nbsp;setelah&nbsp;ditandatangani&nbsp;kedua&nbsp;belah&nbsp;pihak&nbsp;untuk&nbsp;dipergunakan&nbsp;sebagaimana&nbsp;mestinya.</p>','2026-05-29','M.Arief Widhiyanto','SM HCM & Logistic','Nava Gia Ginasta, M.Kom','Direktur Utama','<p>Berdasarkan:</p><ol><li>Kontrak&nbsp;Perjanjian&nbsp;Kerja&nbsp;Sama&nbsp;<strong>Support&nbsp;Pengembangan&nbsp;&amp;&nbsp;Pemeliharaan&nbsp;Aplikasi&nbsp;Dana&nbsp;Pensiun&nbsp;Telkom</strong>&nbsp;No:&nbsp;<strong>Tel.23/LG&nbsp;270/JDPT-0203000/2026</strong>&nbsp;ta